) AS (
  VALUES 
    (123::BIGINT, 'Que profesora más intensa. Pide tener la cámara siempre encendida. El curso es compartido con otro profesor pero cuando lo da ella, es demasiado aburrido. Solo pasa poniendo videos en lugar de explicar. Usa las 4 horas completas de clase entonces se vuelve demasiado cansado.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2026-10-02T00:00:00+00:00'::TIMESTAMPTZ, '2bcba9ba57ccd92b17d7006905fb38cf57dcc0e22273fc0a31e3d47f68acb3bb'::TEXT, ARRAY[1357]::BIGINT[]),
    (123::BIGINT, 'Muy buena profesora y los exámenes son fáciles'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, '31f9af82e9a3529381d78f9315fcc885217701618dc1281fd8a9df7ed2fd1092'::TEXT, ARRAY[2456]::BIGINT[]),
    (123::BIGINT, 'La profesora es sumamente inteligente, pero puede llegar a ser tosca. Le interesa muchísimo la realidad nacional y que uno conozca la legislación. Si participas le caes bien. Tiene favoritos, pero no es una bendición para ellos jajaja por que los agarra en todas las clases. Se acuerda de nombres.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2025-12-10T00:00:00+00:00'::TIMESTAMPTZ, '4b71a5777348c17ea7b0737db4b46fef8d502b9ebdc2e0bba7d33323eb160538'::TEXT, ARRAY[3264]::BIGINT[]),
    (123::BIGINT, 'Te puedes eximir para no hacer el 3er examen. Son clases de prestar atención xq la mayoría es ella hablando de los temas así que tome nota porque realmente todo lo que habla sale en los exámenes y así se vuelve más fácil. Ensayo súper fácil. Exámenes de marque con X únicamente. Escríbale por ayuda.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'b4c66da27c10b659d5a78d846ec8bf84a4afd243a81a0edc53446dea2141fc35'::TEXT, ARRAY[2456]::BIGINT[]),
    (123::BIGINT, 'La profe es muy buena nota, el unico problema es que pone videos muy aburridos y largos, de fijo por ser humanistica, pero es muy facil pasar entonces de fijo lo pueden llevar con ella, se nota que le apasionan los temas que da.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2025-05-13T00:00:00+00:00'::TIMESTAMPTZ, 'fa22f9eefc13979b6582c8e25f9c239e3145dddccce21d994f34df31eabdaa22'::TEXT, ARRAY[648]::BIGINT[]),
    (123::BIGINT, 'Exime. Es muy apasionada y le encanta que sus estudiantes sepan de la realidad nacional (saber de noticias recientes, conocer de la constitucion politica...). Es medio arrancada, la clase y qué tan rudo califica depende del estado de ánimo del día. Pero igual, es difícil perder ese curso.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2024-07-26T00:00:00+00:00'::TIMESTAMPTZ, '11bb0bb4a462a5d1418d5247366041cbe484e97932dee559dc2f53365f695382'::TEXT, ARRAY[3264]::BIGINT[]),
    (123::BIGINT, 'Excelente profesora, explica super bien. Se nota que le gusta lo que hace y es muy chistosa, cae super bien Manda mucho para leer, pero son temas muy bases. La clase es muy entretenida, es muy dinámica (apunte muy bien todo). Los exámenes son faciles y las tareas minimas. La super recomiendo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Requiere mucha lectura']::TEXT[], '2024-06-27T00:00:00+00:00'::TIMESTAMPTZ, '9a4dafb3e1a5361ee93e753a0491985d43d90712486e50f3356d9e176b6f5fb4'::TEXT, ARRAY[629]::BIGINT[]),
    (123::BIGINT, 'La profe es medio peculiar a veces pero es buena gente y hace la clase entretenida. La parte con ella se baso en 2 trabajos en clase que eran faciles. Se ven varios documentales y ella si da toda la clase'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2023-11-19T00:00:00+00:00'::TIMESTAMPTZ, '285bb94b5667c40aa2deb543f501e56f96e0c85c683f037fd8af8418a6553c9a'::TEXT, ARRAY[1357]::BIGINT[]),
    (123::BIGINT, 'La profe le interesa que uno aprenda para la vida, tampoco es muy dura, en virtual se pasa chill, depende el interés en el curso, es muy sencillo como para quedarse. Deja trabajos en clase y un proyecto corto. Le gusta que participen y si no contesta queda ausente.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2023-10-26T00:00:00+00:00'::TIMESTAMPTZ, 'e39f60091c852c72bed3c21a73a6389813eef396c392f69cc265912fc2349c7e'::TEXT, ARRAY[2456]::BIGINT[]),
    (123::BIGINT, 'La profe es bastante buena, se nota que le gusta hablar de los temas que da. Sin embargo, como las clases no tienen tema definido, la profe suele desviarse al punto en que no queda realmente claro qué sale en las evaluaciones. Es como un curso al que se le da forma sobre la marcha.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '201b4feeca888ee37c9d0ff48448740acd0121650eb009ea09fc7bfc6d570baf'::TEXT, ARRAY[3176, 3177, 3264]::BIGINT[]),
    (123::BIGINT, 'Hace exámenes cuando le da la gana aunque valen 5%, pero si usted falto F, pierde 5%, lo bueno es que al final deja eximir a la gente y ayuda a que otros también se eximan, todo GOOD. Arrogante como ella sola, pero bueno es pasable.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2023-03-03T00:00:00+00:00'::TIMESTAMPTZ, '6334d284363512116045277d3700d188884db14429c9cc1a728ff4a21e3152de'::TEXT, ARRAY[2456]::BIGINT[]),
    (123::BIGINT, 'Puede parecer arrogante al principio, pero conforme pasa el curso es muy amable, hace todo lo posible para que el estudiante pueda pasar, deja muchas lecturas y en ocasiones documentales, aveces se desvía de los temas de la clase, pero en general es muy buena profesional'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa']::TEXT[], '2023-01-30T00:00:00+00:00'::TIMESTAMPTZ, '835b3a0ff1c4ef06efa3189a0bdf2bd0126d4cc667d7ca209847202a62439ef0'::TEXT, ARRAY[278]::BIGINT[]),
    (123::BIGINT, 'La doñita se saca exámenes de c*lo, solo decía hoy haremos una parte del examen que vale 5% y eso era todo, nunca se sabía las notas re lerda también. Muy desordenada, pero se puede eximir es ganancia. Un poco arrogante no lo niego.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Exámenes retadores', 'Clases largas']::TEXT[], '2022-12-03T00:00:00+00:00'::TIMESTAMPTZ, '943db856357a3ef679dff6e660ae594adcbff7fe507909cdb33abd42fa2ba034'::TEXT, ARRAY[2456]::BIGINT[]),
    (123::BIGINT, 'La mitad del curso que es con ella es bastante relajado, un trabajo grupal y un ensayo ahí en clase que se hace rapidito. Lo único aburrido es que, si da la clase casi completa (el otro profe da hora y media) y es estar ahí escuchandola hablar y viendo documentales, pero se pasa fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2022-11-27T00:00:00+00:00'::TIMESTAMPTZ, '3f31ca3b4aa2818db26b94d2101ad43a39d46f2eebff589f83b43b2e610060e9'::TEXT, ARRAY[1357]::BIGINT[]),
    (123::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2022-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'c261862705f3105cc38b0ab2868cd606ed017dea0c2e1fcacec31cc20f0c297d'::TEXT, ARRAY[1357]::BIGINT[]),
    (123::BIGINT, 'Se puede notar un poco arrogante al dar la clase por lo que estresa escucharla, y obliga a participar. Igual no da clase, solo pone videos. Es desordenada, necesita como 2 asistentes que hagan todo por ella. Sin embargo, con un buen grupo de trabajo pasa el curso fácil.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '696d82c69879e58e8153d30c068c0b47266b1e20b148bacc0c4e5e83f7e56db7'::TEXT, ARRAY[3264]::BIGINT[]),
    (123::BIGINT, 'La profe es algo intensa y fuerza a participar en clase. La clase es más que todo una conversación y carece de una estructura lo cual se torna un poco confuso. Califica suave y los proyectos no son dificiles por lo cual el curso es ameno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-13T00:00:00+00:00'::TIMESTAMPTZ, '4deb41ae837978ff9d30c8bfa4c08e98257ec914c615be7d61c003f14d2ebbde'::TEXT, ARRAY[3176, 3177, 3264]::BIGINT[]),
    (123::BIGINT, 'La profe es buena, sin embargo, la clase es mas un conversatorio que una clase, al final se acumulan los trabajos y los deja a lo ultimo, en la clase vemos videos muy interesantes y los exámenes son de desarrollo. Las asignaciones son confusas pero la materia es muy interesante, se aprende mucho'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2022-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'c26ef4cbf7dea5134713ebca625a6a44e08faca58bfc4162e393c25054f6ca7b'::TEXT, ARRAY[3264]::BIGINT[]),
    (123::BIGINT, 'Buena profesora, las clases pueden tornarse largas pero si le gustan las leyes, le va a encantar. Los exámenes son un poco difíciles pero no es nada que no pueda encontrar en el material que ella da. Hace actividades remediales para subir la nota y da la oportunidad de eximirse del último examen.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Da crédito extra']::TEXT[], '2022-01-30T00:00:00+00:00'::TIMESTAMPTZ, '0c86c5bffc9f1d7360d2849a36f4ae76fb7049fcf90d78c1fc51dc3f22d406fe'::TEXT, ARRAY[2445]::BIGINT[]),
    (123::BIGINT, '(Verano). Da la clase de una forma en la que los estudiantes tienen que participar sí o sí. Cuesta mucho que conteste las dudas. Calificó a última hora todos los trabajos.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2022-01-27T00:00:00+00:00'::TIMESTAMPTZ, '8d245416161479f18a73127d73c52117a72eddc4e851e83c597d3c9259728797'::TEXT, ARRAY[3264]::BIGINT[]),
    (123::BIGINT, 'Esta profe es lo mejor, ni lo dude con ella'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2021-12-10T00:00:00+00:00'::TIMESTAMPTZ, 'f6b157b00fa6425252ec91d8018a1eba4016fe66b8d736be404e91b5ac9349c0'::TEXT, ARRAY[867]::BIGINT[]),
    (123::BIGINT, 'Excelente profesora, le gusta conversar y debatir la información, promueve el razonamiento y la interpretación personal, hay que leer claro esta pero nada fuera de lo normal, la recomiendo al 100%.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, '7eb91e6053b5ea67eb23370a00843a2736de5e90e8b14315c7b696d00e7d2e13'::TEXT, ARRAY[1477]::BIGINT[]),
    (123::BIGINT, 'Es una excelente profesora, brinda bastante apoyo en horas de consulta, pero por correo NUNCA. Las clases son bastante largas y se tornan aburridas porque es solamente escuchar a la profesora hablando. Hace actividades remediales y está la posibilidad de eximirse del examen final.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2021-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'f98780e7403ff71bb8922c2c5b40160ebac1560a5c4cfe894854080d449ce198'::TEXT, ARRAY[2445]::BIGINT[]),
    (123::BIGINT, 'La profe da las clases muy entretenidas, utiliza videos, documentales y diapositivas para ejemplificar. Excelente!'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, '565eae4c85b0cfc9bbd8268d9e5a881af5aff24f0bdcb91d1715e748b392ddab'::TEXT, ARRAY[2456]::BIGINT[]),
    (123::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'La participación importa', 'Pocos exámenes']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'e6fb9c5f9041d10124e8be248ae91788b7579b49557d953df5d61cbeacd8b1a4'::TEXT, ARRAY[2456]::BIGINT[]),
    (123::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-13T00:00:00+00:00'::TIMESTAMPTZ, 'd2586d58fcd16c07d93de1057267c75134fac9ec208e915c18027dea7803323f'::TEXT, ARRAY[2445]::BIGINT[]),
    (123::BIGINT, 'Es muy buena profe, conoce mucho del tema. Los exámenes son sencillos y disfrutables, deja lecturas para leer por lo que sí toma su tiempo. Los temas abordados son interesantes. Le interesa que los estudiantes participen en clase pero no es obligatorio.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, '2c8ab6ac1406cb5b753f79a960bec7d2ea67e100f4443d1c16341436d85b346a'::TEXT, ARRAY[3264]::BIGINT[]),
    (123::BIGINT, 'Excelente profesora, se aprende mucho. Se nota que sabe y le apasionan los temas que enseña. Le gusta que haya participación por parte de los estudiantes. Los trabajos que deja son claros y se sacan bastante bien si los relaciona a lo que se ve en el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases excelentes']::TEXT[], '2021-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'e2f434cf621192294b64ea24b6d47469099c853cbef5a1b031b9792c81618d96'::TEXT, ARRAY[1357]::BIGINT[]),
    (123::BIGINT, 'Excelente profesora, las clases son muy interesantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, '34bae47f54d6f6f0514f9fce134aec4b5cb40aa8c8dd74ed82af93ef00964d4d'::TEXT, ARRAY[278]::BIGINT[]),
    (123::BIGINT, 'El curso lo dieron la profesora Peláez y el profesor Javier Murillo. La segunda parte (correspondiente a legislación por parte de la profe) fue excelente. Ella da clase magistral pero es abierta a debate, de hecho, es lo que más le gusta. Los exámenes son de opinión y la verdad son disfrutables.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, '51f3e8a581c9876fe49fa5c50f8b4b54bf6b41fa853d9d16ebc1671fa769bebb'::TEXT, ARRAY[1357]::BIGINT[]),
    (123::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'e1f4c2219f55c5ae5474cdd367c90f2a1d8b93d4bc4a0e648985de80a3be4fca'::TEXT, ARRAY[2445]::BIGINT[]),
    (123::BIGINT, 'En un inicio parece ser muy estricta y seria, pero en realidad es muy colaborativa y siempre está anuente a ayudar, Matriculen sin miedo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'f84303ee655dfdcb56edeedc19bb74ab48aafc9a6ae40401f0f21e1d9899a896'::TEXT, ARRAY[2445]::BIGINT[]),
    (123::BIGINT, 'Explica claro, los exámenes son exactamente lo que ella explica en clase (les aconsejo leer las tareas que deje), da muy buenos ejemplos. El proyecto es de llevarla al día y así se les hará sencillo.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-23T00:00:00+00:00'::TIMESTAMPTZ, '06ae0a2c2d408cd3351ed15bd50f014fb0cd2fec89bf5ca0522bb0d3e5267cad'::TEXT, ARRAY[2445]::BIGINT[]),
    (123::BIGINT, 'Matriculen con ella sin miedo. Sin duda el curso se vuelve súper interesante (yo al inicio estaba medio agüevado porque era de derecho y la verdad qué pereza) pero en serio con ella es súper interesante, le transmite a uno las ganas de aprender sobre derecho. Se interesa porque todo quede claro.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2020-12-26T00:00:00+00:00'::TIMESTAMPTZ, '90e54f981e6e34a0cca9f64e279a5bc870d210257a2a9a70550f89d44f88b8f5'::TEXT, ARRAY[1477]::BIGINT[]),
    (123::BIGINT, 'Excelente profesora.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-12-10T00:00:00+00:00'::TIMESTAMPTZ, '295a6f5a8cdec0cf632dc9e30ada92c750c9096a2670245a5332ea64db603e27'::TEXT, ARRAY[3176, 3177, 3264]::BIGINT[]),
    (123::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '6ea6c6bb7476f1f7eed2f5d22bdea9ae20bdd7bf1bdf89b8a7f899a0cb0f2927'::TEXT, ARRAY[3264]::BIGINT[]),
    (123::BIGINT, '"¿Pero ustedes viven en Costa RIca?" Hay que participar en clase, pone muchos videos o documentales y hay que leer noticias sobre medio ambiente para conversar en clase. 10/10 el curso en verano. Tarda mucho en calificar.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas']::TEXT[], '2020-01-22T00:00:00+00:00'::TIMESTAMPTZ, '71a610abd6df05c6e01ade84d7e6cf679276594bbb992739939ee82b66ed88c8'::TEXT, ARRAY[1357]::BIGINT[]),
    (123::BIGINT, 'Brinda mucho apoyo y hace la clase interesante. Podría resultar un poco intimidante, pero solo es de prestarle atención, participar y opinar. El único detalle es que suele interrumpir mientras uno expone, de ahí en fuera es buena y el curso es fácil :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Brinda apoyo']::TEXT[], '2019-07-25T00:00:00+00:00'::TIMESTAMPTZ, '1e5956d76d5d6e0264ae300e58bb2df3d32e55eda4fa6f832e9cd7c45143e569'::TEXT, ARRAY[3264]::BIGINT[]),
    (123::BIGINT, 'Es una profe relax y hace que el curso sea muy facil. A veces alarga las clases porque habla mucho pero es muy buena profe y pura vida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, '637365a5802a6b54cec0026a9ccee41baa825acdd88a9a08282eb60e4eb3da98'::TEXT, ARRAY[1357]::BIGINT[]),
    (123::BIGINT, 'Es muy relax , solo que en las exposiciones pasa interrumpiendo a los estudiantes.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2018-12-15T00:00:00+00:00'::TIMESTAMPTZ, '017fa6955aa59ae86687288b1d2bdbc522cf05f266fbc9ce176988c30790106f'::TEXT, ARRAY[1357]::BIGINT[]),
    (123::BIGINT, 'Super recomendada, es muy buena gente, chistosa y hace que la clase se pase sola. Explica de más y hace que a uno le termine gustando un montón el curso. Ayuda bastante y a ella le importa que usted aprenda de verdad.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Inspirador']::TEXT[], '2018-11-22T00:00:00+00:00'::TIMESTAMPTZ, '01ce52a80942bd76bcfc6ec5635fc6cb99318ed92baf6c4d6b58e7b80d5faeb9'::TEXT, ARRAY[629]::BIGINT[]),
    (123::BIGINT, 'Excelente profesora, explica súper bien y hace prácticas que ayudan demasiado para los exámenes. Le gusta que participen, es divertida y califica suave.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'f1e7ea0cebdfe207ca8ceb409f9c5a1f5021f6fde42750731d6bafae192a65cb'::TEXT, ARRAY[629]::BIGINT[]),
    (123::BIGINT, 'Excelente profesora. Se interesa por el aprendizaje e interes del estudiante. Califica suave. El trabajo de investigación debe estar bien hecho. Las clases son muy buenas y entretenidas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '9c64b4c495cd7a5db3d40df105076cd41c018b2b211b253ff669dd1e39ae1cef'::TEXT, ARRAY[629]::BIGINT[]),
    (123::BIGINT, 'Habla muy duro e interrumpe en clases'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-20T00:00:00+00:00'::TIMESTAMPTZ, '17ae3fdac339a146b7a42c6ea32ffd14e7ea0d4b24727dbd41b3a6dc80aa0e01'::TEXT, ARRAY[3264]::BIGINT[]),
    (123::BIGINT, 'Al principio parece ser demasiado arrogante pero en realidad es muy buena gente y graciosa. Las clases son entretenidas y explica todo lo que se ocupa para el examen que ni se ocupa el Código. Si no quieren una hablada incómoda, no le hablen de la marihuana.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '6900af669ef15f8897732c10cfaf1e0b30aee8b8622fd1528745a5e25995aaaf'::TEXT, ARRAY[629]::BIGINT[]),
    (123::BIGINT, 'Excelente profe, explica muy bien, tiene buena presencia y le encanta dar sus clases.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-08T00:00:00+00:00'::TIMESTAMPTZ, '94cfa5d870bc17b2a75a1a8890b1df940767f1e3a28680cb97c86eb32300720d'::TEXT, ARRAY[629]::BIGINT[]),
    (123::BIGINT, 'Super buena nota, explica muy bien y de forma entretenida, califica bien y se preocupa por que usted pase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2018-01-27T00:00:00+00:00'::TIMESTAMPTZ, '11c6032e0f19db10179fbbfed4b9e2eefc17b45be8fa972e6f960cd7dc5373fc'::TEXT, ARRAY[629]::BIGINT[]),
    (123::BIGINT, 'Explica super bien que ni es necesario leer el código de trabajo si uno va a las clases.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'cbe4107ddec2ffd5ab9bfe913f577be117a0c9b3ba8aff3f31a725865a5cd604'::TEXT, ARRAY[629]::BIGINT[]),
    (123::BIGINT, 'muy buena profesora, en clase provoca ponerle atención, super buena gente, explica bastante bien la materia, y super buena gente, ojalá puedan llevar cursos con ella, si tienen la oportunidad, ella deja tareas, algunas un poco largas pero no son todas.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-20T00:00:00+00:00'::TIMESTAMPTZ, '2ec19f2846cd0bb8fd8939e61c923c5b3656eb5649a6882d2a57642f95dcb76e'::TEXT, ARRAY[629]::BIGINT[]),
    (123::BIGINT, 'Al principio las clases son interesantes pero NUNCA abarca la materia en la clase y te toca leerla toda en casa para los exámenes, sabe mucho y es muy buena profesionalmente pero no sabe ser profesora y luego para justificar las notas del curso casi que las pone al azar.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'b011af01357bdf7a1ece57d03f3fea9a7c92dff673a35cd6bba5b7325546ccb4'::TEXT, ARRAY[3264]::BIGINT[]),
    (123::BIGINT, 'Excelente persona, a veces las clases son un tanto aburridas, hay que estudiar bastante para los exámenes porque no explica muy bien'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'cfd669b2f3083f0b1aa2976ec8a9582f6cf61944797252ed1502c5cce1e6f66a'::TEXT, ARRAY[2445]::BIGINT[]),
    (123::BIGINT, 'Se nota que sabe mucho, pero sus clases son muy aburridas. A veces no aclara bien las dudas, no cae ni bien ni mal. No califica rudo, pero en los exámenes entran varas que ella no explicó.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2017-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'c8c1b66a39bf7cc405ec7d4bb1e7b5d8d8222be7fb36d716b0bc1da947e4df0a'::TEXT, ARRAY[2445]::BIGINT[]),
    (123::BIGINT, 'No domina bien la materia, a veces se nota insegura. Además no nos dio materia que sí fue evaluada en el examen de cátedra.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-04-13T00:00:00+00:00'::TIMESTAMPTZ, '97f2ed145a78cfcdccfd68f580ce1548f354c2fa7d3f28113efde702fcbd1ed1'::TEXT, ARRAY[2445]::BIGINT[]),
    (123::BIGINT, 'Es una de esas clases en las que nunca te aburrís. Es una persona excelente. Sabe mucho y te prepara super bien.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2017-03-08T00:00:00+00:00'::TIMESTAMPTZ, '94cdccf4b7a2ac295be3d4da84671c868ce55d693e98e1c1d80b5793a6e70000'::TEXT, ARRAY[2445]::BIGINT[]),
    (123::BIGINT, 'Es toda divertida y es una crack!! Se nota que le gusta lo que hace. Lo único es que aveces deja muchas tareas.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'cd0346e72fdb173b020e2f8bc6fe68c0d910f3f76e43752e5c47691a9f9267b4'::TEXT, ARRAY[629]::BIGINT[]),
    (123::BIGINT, 'Clases interesantes y super amenas. Explica claro y ayuda bastante. Tiene pasión por la materia y la transmite al grupo. Lo pone a uno a trabajar mucho por lo que no se vuelve un curso tan suave.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-25T00:00:00+00:00'::TIMESTAMPTZ, 'cd063175df0969e183edec039934529501771276825966cbbb6368a46ae2d737'::TEXT, ARRAY[629]::BIGINT[]),
    (123::BIGINT, 'es fácil en general, los trabajos son sencillos, aunque es un poco desordenada, los exámenes son muy fáciles. hay que explicarle al menos una noticia relacionada con comercio o derecho comercial.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-21T00:00:00+00:00'::TIMESTAMPTZ, '5628def22a8f97c7c9a4ded2c5d1f1ab59b27e07ca2a6a11bc22d1ed865375ff'::TEXT, ARRAY[2445]::BIGINT[]),
    (123::BIGINT, 'Le interesa mucho que el estudiante aprenda, los exámenes son muy fáciles, es muy flexible con las entregas de trabajos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, '0357027d34a3fc2e953d0735b1444f6d255cf7034976ffb969d3d7162eaa842f'::TEXT, ARRAY[2547]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
